'use client';

import React, { useState } from 'react';
import { Navbar } from '@/components/Navbar';
import { HeroSection } from '@/components/HeroSection';
import { ShopSection } from '@/components/ShopSection';
import { CustomQuoteSection } from '@/components/CustomQuoteSection';
import { HowItWorksSection } from '@/components/HowItWorksSection';
import { Footer } from '@/components/Footer';
import { CartDrawer, CartItem } from '@/components/CartDrawer';
import { ShoppingBag, ArrowRight } from 'lucide-react';

export default function Home() {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const handleAddToCart = (item: { id: string; name: string; price: number; meta?: string }) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) {
        return prev.map(i => i.id === item.id ? { ...i, qty: i.qty + 1 } : i);
      }
      return [...prev, { ...item, qty: 1 }];
    });
  };

  const handleBuyNow = (item: { id: string; name: string; price: number; meta?: string }) => {
    handleAddToCart(item);
    setIsCartOpen(true);
  };

  const handleUpdateQty = (id: string, delta: number) => {
    setCart(prev => {
      return prev
        .map(item => {
          if (item.id === id) {
            const newQty = item.qty + delta;
            return newQty > 0 ? { ...item, qty: newQty } : null;
          }
          return item;
        })
        .filter(Boolean) as CartItem[];
    });
  };

  const handleRemoveItem = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const handleClearCart = () => {
    setCart([]);
  };

  const totalCartCount = cart.reduce((sum, item) => sum + item.qty, 0);
  const totalAmount = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);

  return (
    <main>
      <Navbar cartCount={totalCartCount} onOpenCart={() => setIsCartOpen(true)} />
      
      {/* Hero with live seamless 3D simulation */}
      <HeroSection />
      
      {/* Pillar 1: Pre-printed E-Commerce Store */}
      <ShopSection onAddToCart={handleAddToCart} onBuyNow={handleBuyNow} />

      {/* Pillar 2: Custom 3D Printing & CAD Quote Engine */}
      <CustomQuoteSection />

      {/* Simple 3-Step Process */}
      <HowItWorksSection />

      {/* Footer */}
      <Footer />

      {/* Slide-out Cart Drawer with WhatsApp Order & UPI simulator */}
      <CartDrawer
        isOpen={isCartOpen}
        onClose={() => setIsCartOpen(false)}
        cart={cart}
        onUpdateQty={handleUpdateQty}
        onRemoveItem={handleRemoveItem}
        onClearCart={handleClearCart}
      />

      {/* Floating Cart Trigger Pill */}
      {totalCartCount > 0 && !isCartOpen && (
        <div
          style={{
            position: 'fixed',
            bottom: '24px',
            right: '24px',
            zIndex: 400,
            background: 'var(--navy)',
            color: '#FFFFFF',
            padding: '12px 20px',
            borderRadius: '50px',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
            boxShadow: '0 12px 35px rgba(10, 13, 20, 0.35)',
            cursor: 'pointer',
            border: '1px solid rgba(255, 255, 255, 0.15)'
          }}
          onClick={() => setIsCartOpen(true)}
        >
          <span style={{ background: 'var(--green-ink)', color: '#FFFFFF', padding: '2px 8px', borderRadius: '12px', fontSize: '11px', fontWeight: 800 }}>
            {totalCartCount}
          </span>
          <span style={{ fontSize: '13px', fontWeight: 800 }}>Review Cart (₹{totalAmount}) &rarr;</span>
        </div>
      )}
    </main>
  );
}
